<?= $this->extend('layouts/main') ?><?= $this->section('content') ?>
<?php $editing=$user!==null; $errors=session()->getFlashdata('errors') ?? []; ?>
<header class="page-head"><p class="kicker">Staff register</p><h1><?= $editing?'Edit staff account':'New staff account' ?></h1><p><?= $editing?'Update identity, access, or profile image.':'Create protected access for a team member.' ?></p></header>
<?php if($avatarNotice): ?><div class="flash flash-info" role="status"><strong>Avatar storage:</strong> <?= esc($avatarNotice) ?></div><?php endif ?>
