<div class="form-grid"><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" maxlength="50" required value="<?= esc(old('username',$user['username']??'')) ?>" <?= isset($errors['username'])?'aria-invalid="true" aria-describedby="username-error"':'' ?>><p class="hint">Letters, numbers, dots, hyphens, and underscores.</p><?php if(isset($errors['username'])):?><p class="field-error" id="username-error"><?= esc($errors['username']) ?></p><?php endif ?></div>
